mapper.select:
SELECT a.lesson_id 
FROM biz_student_answer a
WHERE a.student_id = #{studentId}
  AND YEAR(a.submit_time) = #{year}
GROUP BY a.lesson_id
ORDER BY MAX(a.submit_time) DESC

SELECT lq.lesson_id AS lessonId, lq.question_id AS questionId, COALESCE(lq.question_score, 0) AS questionScore, lq.order_num AS orderNum, q.question_content AS questionContent, q.question_type AS questionType, q.option_a AS optionA, q.option_b AS optionB, q.option_c AS optionC, q.option_d AS optionD, q.answer, q.analysis, q.typing_duration AS typingDuration, q.word_count AS wordCount, q.preview_path AS previewPath, q.file_path AS filePath, a.student_answer AS studentAnswer FROM biz_student_answer a INNER JOIN (
) latest ON latest.answer_id = a.answer_id LEFT JOIN biz_question q ON a.question_id = q.question_id LEFT JOIN biz_lesson_question lq ON a.question_id = lq.question_id AND a.lesson_id = lq.lesson_id WHERE a.student_id = #{studentId} AND a.is_correct = 0 AND q.question_type IN ('choice', 'judgment')
AND a.lesson_id = #{lessonId}
ORDER BY a.submit_time DESC

SELECT a.answer_id AS answerId, s.student_id AS studentId, u.nick_name AS studentName, s.student_no AS studentNo, s.class_code AS classCode, s.remark AS remark, #{questionId} AS questionId, q.question_content AS questionContent, a.student_answer AS studentAnswer, a.preview_status AS previewStatus, a.preview_path AS previewPath, a.preview_retry_count AS previewRetryCount, a.preview_last_retry_time AS previewLastRetryTime, a.preview_error_message AS previewErrorMessage, a.score AS score, lq.question_score AS maxScore, a.submit_time AS submitTime, CASE WHEN a.answer_id IS NOT NULL THEN 1 ELSE 0 END AS submitted FROM biz_student s LEFT JOIN sys_user u ON s.user_id = u.user_id LEFT JOIN ( SELECT a1.* FROM biz_student_answer a1 INNER JOIN (
) latest ON latest.answer_id = a1.answer_id ) a ON s.student_id = a.student_id AND a.lesson_id = #{lessonId}
AND a.question_id = #{questionId}
LEFT JOIN biz_question q ON q.question_id = #{questionId} LEFT JOIN biz_lesson_question lq ON lq.question_id = #{questionId} AND lq.lesson_id = #{lessonId} WHERE s.class_code = #{classCode} AND s.entry_year = #{entryYear} AND u.dept_id = #{deptId} ORDER BY CAST(s.student_no AS UNSIGNED) ASC

mapper.update:
UPDATE biz_student_answer 
SET score = #{score}
WHERE answer_id = #{answerId}

mapper.select:
SELECT a.student_id AS studentId, a.lesson_id AS lessonId, l.lesson_title AS lessonTitle, l.lesson_num AS lessonNum, SUM(CASE WHEN q.question_type = 'typing' THEN IFNULL(a.score, 0) ELSE 0 END) AS typingScore, SUM(CASE WHEN q.question_type IN ('choice', 'judgment') THEN IFNULL(a.score, 0) ELSE 0 END) AS theoryScore, SUM(CASE WHEN q.question_type = 'practical' THEN IFNULL(a.score, 0) ELSE 0 END) AS practicalScore, SUM(IFNULL(a.score, 0)) AS totalScore, -- 打字统计（只取打字题的平均值） ROUND(AVG(CASE WHEN q.question_type = 'typing' THEN a.typing_speed ELSE NULL END), 0) AS avgTypingSpeed, ROUND(AVG(CASE WHEN q.question_type = 'typing' THEN a.accuracy_rate ELSE NULL END), 1) AS avgAccuracyRate, ROUND(AVG(CASE WHEN q.question_type = 'typing' THEN a.completion_rate ELSE NULL END), 1) AS avgCompletionRate FROM biz_student_answer a INNER JOIN (
) latest ON latest.answer_id = a.answer_id LEFT JOIN biz_lesson l ON a.lesson_id = l.lesson_id LEFT JOIN biz_question q ON a.question_id = q.question_id WHERE a.student_id = #{studentId}
AND a.lesson_id = #{lessonId}
GROUP BY a.student_id, a.lesson_id, l.lesson_title, l.lesson_num ORDER BY l.lesson_num

SELECT a.student_id AS studentId, a.lesson_id AS lessonId, l.lesson_title AS lessonTitle, l.lesson_num AS lessonNum, SUM(CASE WHEN q.question_type = 'typing' THEN IFNULL(a.score, 0) ELSE 0 END) AS typingScore, SUM(CASE WHEN q.question_type IN ('choice', 'judgment') THEN IFNULL(a.score, 0) ELSE 0 END) AS theoryScore, SUM(CASE WHEN q.question_type = 'practical' THEN IFNULL(a.score, 0) ELSE 0 END) AS practicalScore, SUM(IFNULL(a.score, 0)) AS totalScore, ROUND(AVG(CASE WHEN q.question_type = 'typing' THEN a.typing_speed ELSE NULL END), 0) AS avgTypingSpeed, ROUND(AVG(CASE WHEN q.question_type = 'typing' THEN a.accuracy_rate ELSE NULL END), 1) AS avgAccuracyRate, ROUND(AVG(CASE WHEN q.question_type = 'typing' THEN a.completion_rate ELSE NULL END), 1) AS avgCompletionRate FROM biz_student_answer a INNER JOIN (
) latest ON latest.answer_id = a.answer_id LEFT JOIN biz_lesson l ON a.lesson_id = l.lesson_id LEFT JOIN biz_question q ON a.question_id = q.question_id WHERE a.student_id IN
#{studentId}
AND a.lesson_id IN
#{lessonId}
GROUP BY a.student_id, a.lesson_id, l.lesson_title, l.lesson_num ORDER BY a.student_id, l.lesson_num

mapper.update:
UPDATE biz_student_answer
SET preview_status = 'converting',
    preview_path = NULL,
    preview_retry_count = #{nextRetryCount},
    preview_last_retry_time = #{claimedAt},
    preview_error_message = NULL
WHERE answer_id = #{answerId}
  AND preview_path IS NULL
  AND preview_status = #{expectedStatus}
  AND IFNULL(preview_retry_count, 0) = #{expectedRetryCount}
  AND (
        (#{expectedLastRetryTime} IS NULL AND preview_last_retry_time IS NULL)
     OR preview_last_retry_time = #{expectedLastRetryTime}
  )

mapper.select:
SELECT COUNT(DISTINCT s.student_id)
FROM biz_student s
INNER JOIN sys_user u ON u.user_id = s.user_id
LEFT JOIN (
    SELECT DISTINCT a.student_id
    FROM biz_student_answer a
    INNER JOIN (

    ) latest ON latest.answer_id = a.answer_id
    WHERE a.lesson_id = #{lessonId}
) ans ON ans.student_id = s.student_id
LEFT JOIN biz_classroom_performance p
    ON p.student_id = s.student_id
    AND p.lesson_id = #{lessonId}
WHERE s.class_code = #{classCode}
  AND s.entry_year = #{entryYear}
  AND u.dept_id = #{deptId}
  AND IFNULL(p.is_absent, 0) = 0
  AND (ans.student_id IS NOT NULL OR p.performance_id IS NOT NULL)
